module top_module(clk, clk_ena, rst, q);parameter ADDR_MOD = 512;
  parameter ADDR_WIDTH = 9;

  input clk, clk_ena, rst;
  output [ADDR_WIDTH-1:0] q;
  //output carry;

  // local
  reg [ADDR_WIDTH-1:0] cnt;
  reg carry_tmp;
  // logic
  always @ (posedge clk or posedge rst)
    begin
    if(rst)
      cnt <= 0;
    else if(clk_ena)
      cnt <= (cnt + 1)%ADDR_MOD;
  end
  // комб. часть - перенос
  always @ (cnt)
    begin
    if(cnt == ADDR_MOD-1)
      carry_tmp = 'b1;
    else 
      carry_tmp = 'b0;
  end
  //
  assign q = cnt;
endmodule

