description:
Design a spread-spectrum clock generator (SSCG) that modulates a reference clock signal based on a selected spread percentage. The module takes a reference clock input and a two-bit spread selection input, which determines the modulation amplitude. It generates a clock output that varies in frequency within a specified modulation rate, effectively spreading the clock signal to reduce electromagnetic interference. The design utilizes counters to control the timing of clock toggling and ensures that the output clock pulse width and frequency are adjusted according to the selected spread rate.
module top_module(
  input clk_ref,
  input [1:0] spread_sel,
  output reg clk_sscg
);

code:
module top_module(
  input clk_ref,
  input [1:0] spread_sel,
  output reg clk_sscg
);parameter spread_rate = 5; // in percentage
parameter mod_rate = 10000; // in Hz

reg [31:0] cnt;
reg [31:0] mod_cnt;
reg [31:0] tri_cnt;
reg [31:0] tri_amp;

always @(posedge clk_ref) begin
  cnt <= cnt + 1;
  mod_cnt <= mod_cnt + 1;
  tri_cnt <= tri_cnt + 1;

  if (mod_cnt >= (50000000 / mod_rate)) begin
    mod_cnt <= 0;
  end

  if (tri_cnt >= (50000000 / (2 * mod_rate))) begin
    tri_cnt <= 0;
  end

  if (cnt >= (50000000 / (2 * mod_rate))) begin
    cnt <= 0;
  end

  if (spread_sel == 2'b00) begin
    tri_amp <= (50000000 * spread_rate) / (100 * mod_rate);
  end else if (spread_sel == 2'b01) begin
    tri_amp <= (50000000 * 2 * spread_rate) / (100 * mod_rate);
  end else if (spread_sel == 2'b10) begin
    tri_amp <= (50000000 * 3 * spread_rate) / (100 * mod_rate);
  end else if (spread_sel == 2'b11) begin
    tri_amp <= (50000000 * 4 * spread_rate) / (100 * mod_rate);
  end

  if (tri_cnt < tri_amp) begin
    clk_sscg <= 1;
  end else begin
    clk_sscg <= 0;
  end

  if (mod_cnt < (tri_amp / 2)) begin
    clk_sscg <= clk_sscg ^ 1;
  end
end

endmodule

