module top_module_tb;

    // Testbench signals (combinational circuit)
    reg [3:0] A;
    reg [3:0] B;
    reg SUB;
    wire [3:0] SUM;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .A(A),
        .B(B),
        .SUB(SUB),
        .SUM(SUM)
    );
    task testcase001;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Simple Addition (3 + 4)", test_num);
        A = 4'd3;
        B = 4'd4;
        SUB = 1'b0;
        #1;

        check_outputs(4'd7);
    end
        endtask

    task testcase002;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Simple Subtraction (10 - 3)", test_num);
        A = 4'd10;
        B = 4'd3;
        SUB = 1'b1;
        #1;

        check_outputs(4'd7);
    end
        endtask

    task testcase003;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Addition with Overflow (12 + 5)", test_num);

        A = 4'd12;
        B = 4'd5;
        SUB = 1'b0;
        #1;

        check_outputs(4'd1);
    end
        endtask

    task testcase004;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Subtraction resulting in Negative (2's Complement: 4 - 6)", test_num);

        A = 4'd4;
        B = 4'd6;
        SUB = 1'b1;
        #1;

        check_outputs(4'd14);
    end
        endtask

    task testcase005;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Addition of zero (8 + 0)", test_num);
        A = 4'd8;
        B = 4'd0;
        SUB = 1'b0;
        #1;

        check_outputs(4'd8);
    end
        endtask

    task testcase006;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Subtraction by zero (15 - 0)", test_num);
        A = 4'd15;
        B = 4'd0;
        SUB = 1'b1;
        #1;

        check_outputs(4'd15);
    end
        endtask

    task testcase007;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Subtraction from zero (0 - 1)", test_num);

        A = 4'd0;
        B = 4'd1;
        SUB = 1'b1;
        #1;

        check_outputs(4'd15);
    end
        endtask

    task testcase008;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Maximum values subtraction (15 - 15)", test_num);
        A = 4'hF;
        B = 4'hF;
        SUB = 1'b1;
        #1;

        check_outputs(4'd0);
    end
        endtask

    task testcase009;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Maximum values addition (15 + 15)", test_num);

        A = 4'hF;
        B = 4'hF;
        SUB = 1'b0;
        #1;

        check_outputs(4'hE);
    end
        endtask

    task testcase010;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Alternating SUB bit for same values", test_num);
        A = 4'd5;
        B = 4'd2;
        SUB = 1'b0;
        #1;
        SUB = 1'b1;
        #1;

        check_outputs(4'd3);
    end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("top_module Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();
        testcase007();
        testcase008();
        testcase009();
        testcase010();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
