description:
Design a circuit that generates a divided clock signal. It takes a clock input and a reset input, producing a single output clock signal that toggles at a lower frequency defined by a 16-bit counter. The counter counts up to a specified value (56187) and resets back to zero, while the output `clk_div` is derived from the most significant bit of the counter, allowing for the creation of a clock with a frequency that is a fraction of the input clock frequency.
module top_module(
		clk,
		rst_n,
		clk_div
    );

code:
module top_module(
		clk,
		rst_n,
		clk_div
    );input clk,rst_n;
    output clk_div;
    reg clk_div;

    reg [15:0] counter;

always @(posedge clk or negedge rst_n)
	if(!rst_n)
		counter <=0;
	else if (counter==56187)
		counter <=0;
	else
		counter<=counter+1;
	assign clk_div = counter[15];		
endmodule

