module fsm (
  input in,
  input [2:0] state,
  output reg [2:0] next_state,
  output reg out);parameter A=0, B=1, C=2, D=3, E=4;

    always_comb begin
        case (state)
            A: next_state = in ? C : B;
            B: next_state = in ? D : A;
            C: next_state = in ? B : E;
            D: next_state = in ? A : C;
            E: next_state = in ? C : D;
        endcase
    end

    assign out = (state==B) || (state==D);

endmodule

