module top_module(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    input select,
    output reg [7:0] out
);reg [99:0] shift_reg;
reg [99:0] shifted_data;
reg [7:0] pop_count;

always @(negedge clk) begin
    if (load) begin
        shift_reg <= data;
    end else begin
        if (ena[0]) begin
            shifted_data <= {shift_reg[98:0], shift_reg[99]};
        end else if (ena[1]) begin
            shifted_data <= {shift_reg[0], shift_reg[99:1]}; // Fixed the order of the part select
        end else begin
            shifted_data <= shift_reg;
        end
        shift_reg <= shifted_data;
    end

    if (select) begin
        // Population count circuit
        pop_count <= pop_count + (shifted_data[99] + shifted_data[98] + shifted_data[97] + 
                                   shifted_data[96] + shifted_data[95] + shifted_data[94] + 
                                   shifted_data[93] + shifted_data[92]); // Fix: cumulative pop_count
        out <= pop_count;
    end else begin
        // Rotator module
        out <= shifted_data;
    end
end

endmodule

