module top_module(
    input clk_i,
    input rst_i,
    input hours_btn_i,
    input mins_btn_i,
    output reg [3:0] digits_o
);reg [3:0] hours;
reg [3:0] mins;
reg [1:0] state;

parameter S_IDLE = 2'b00;
parameter S_HOURS = 2'b01;
parameter S_MINS = 2'b10;

always @(posedge clk_i, posedge rst_i) begin
    if (rst_i) begin
        hours <= 4'b0000;
        mins <= 4'b0000;
        state <= S_IDLE;
    end else begin
        case (state)
            S_IDLE: begin
                digits_o <= {4'b0000, 4'b0000};
                if (hours_btn_i) begin
                    state <= S_HOURS;
                end else if (mins_btn_i) begin
                    state <= S_MINS;
                end
            end
            S_HOURS: begin
                if (mins_btn_i) begin
                    hours <= hours + 1;
                end
                digits_o <= {4'b0000, hours};
                if (!hours_btn_i) begin
                    state <= S_IDLE;
                end
            end
            S_MINS: begin
                if (mins_btn_i) begin
                    mins <= mins + 1;
                end
                digits_o <= {4'b0000, mins};
                if (!mins_btn_i) begin
                    state <= S_IDLE;
                end
            end
        endcase
    end
end

endmodule

