module top_module (
        input clk,
        input areset,
        input start_button,
        input stop_button,
        output reg cooking);parameter Idle = 2'b01, Cooking = 2'b10;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Idle;
		else begin
			case (state)
				Idle: state <= start_button ? Cooking : Idle;
				Cooking: state <= stop_button ? Idle : Cooking;
			endcase
		end
	end

	assign cooking = (state == Cooking);
endmodule

