module top_module (
        input clk,
        input areset,
        input start_vent,
        input stop_vent,
        output reg vent_on);parameter Vent_Off=1'b0, Vent_On=1'b1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Vent_Off;
		else begin
			case (state)
				Vent_Off: state <= start_vent ? Vent_On : Vent_Off;
				Vent_On: state <= stop_vent ? Vent_Off : Vent_On;
			endcase
		end
	end

	assign vent_on = (state == Vent_On);

endmodule

