module top_module(Leds,HexVal);output[0:6] Leds;
	input [3:0] HexVal;
	reg   [0:6] Leds;

	always @(HexVal) begin
		case(HexVal)
			4'h0:  Leds = 7'b000_0001;  	
			4'h1:  Leds = 7'b100_1111;  	
			4'h2:  Leds = 7'b001_0010;  	
			4'h3:  Leds = 7'b000_0110;  	
