			4'h6:  Leds = 7'b010_0000;  	
			4'h7:  Leds = 7'b000_1111;  	
			4'h8:  Leds = 7'b000_0000;  	
			4'h9:  Leds = 7'b000_0100;  	
			4'hA:  Leds = 7'b000_1000;  	
			4'hB:  Leds = 7'b110_0000;  	
			4'hC:  Leds = 7'b011_0001;  	
			4'hD:  Leds = 7'b100_0010;  	
			4'hE:  Leds = 7'b011_0000;  	
