module top_module(
    input [7:0] a,
    input [7:0] b,
    input clk,          // Added clk input
    output reg [15:0] product
);reg [7:0] a_reg, b_reg;
reg [3:0] count;
reg [15:0] sum;

always @ (a or b) begin
    a_reg <= a;
    b_reg <= b;
    count <= 4'd0;
    sum <= {8'd0, a_reg};
end

always @ (posedge clk) begin
    if (count < 4'd7) begin
        if (b_reg[0] == 1 && sum[0] == 0) begin
            sum <= sum - a_reg;
        end
        else if (b_reg[0] == 0 && sum[0] == 1) begin
            sum <= sum + a_reg;
        end
        if (sum[0] == 1) begin
            b_reg <= {1'b0, b_reg[7:1]};
        end
        else begin
            b_reg <= {b_reg[7], b_reg[7:1]};
        end
        sum <= {sum[15], sum[15:1]};
        count <= count + 1;
    end
    else begin
        product <= sum;
    end
end

endmodule

