module heating_system (
    input clk,
    input areset,
    input [7:0] temp,
    input mode,
    output reg [1:0] state);

    parameter OFF = 2'b00, HEATING = 2'b01, COOLDOWN = 2'b10;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= OFF;
        end else begin
            case (state)
                OFF: begin
                    if (mode && temp < 8'd20) state <= HEATING;
                    else state <= OFF;
                end
                HEATING: begin
                    if (!mode) state <= OFF;
                    else if (temp >= 8'd20) state <= COOLDOWN;
                    else state <= HEATING;
                end
                COOLDOWN: begin
                    if (!mode) state <= OFF;
                    else state <= COOLDOWN;
                end
            endcase
        end
    end
endmodule

