module counter6bit_rollover (
    input clk,
    input rst,
    output [5:0] q
);

    reg [5:0] q_reg;

    always @(posedge clk or posedge rst) begin
        if (rst)
            q_reg <= 6'b000000;
        else
            q_reg <= q_reg + 1;
    end

    assign q = q_reg;

endmodule

