                $display("  Got:      DSPoflow=%b, dac_clk=%b, fb_cond=%b, pout=%h",
                         DSPoflow, dac_clk, fb_cond, pout);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
