module up_down_counter (
	input clk,
	input reset,
	input dir,
	output reg [3:0] count
);

always @(posedge clk or posedge reset) begin
	if (reset) begin
		count <= 4'b0000;
	end else if (dir) begin
		count <= count + 1;
	end else begin
		count <= count - 1;
	end
end

endmodule

